#include "main_window.hpp"
#include <adwaita.h>
#include <gtkmm/cssprovider.h>
#include <gtkmm/filechoosernative.h>
#include <gtkmm/stylecontext.h>
#include <array>

namespace {
Gtk::Label* text(const Glib::ustring& value, const char* style = "") { auto* w = Gtk::make_managed<Gtk::Label>(value); w->set_halign(Gtk::Align::START); w->set_wrap(); if (*style) w->add_css_class(style); return w; }
void field(Gtk::Box& box, const Glib::ustring& title, Gtk::Widget& widget) { box.append(*text(title, "field-label")); box.append(widget); }
void page(Gtk::Box& box) { box.set_margin(28); box.add_css_class("page"); box.set_valign(Gtk::Align::START); }
Gtk::Button* choice(const Glib::ustring& title) { auto* b = Gtk::make_managed<Gtk::Button>(title); b->add_css_class("menu-choice"); return b; }
}

AgemirWindow::AgemirWindow() {
    runtime_ = agemir_runtime_create(); set_title("Agemir"); set_default_size(860, 720);
    auto css = Gtk::CssProvider::create(); css->load_from_resource("/org/agemir/Agemir/agemir.css"); Gtk::StyleContext::add_provider_for_display(get_display(), css, GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);
    auto* header = Gtk::make_managed<Gtk::HeaderBar>(); auto* home = Gtk::make_managed<Gtk::Button>("Main menu"); home->signal_clicked().connect(sigc::mem_fun(*this, &AgemirWindow::show_main)); header->pack_start(*home); set_titlebar(*header);

    main_page_.append(*text("Agemir", "title")); main_page_.append(*text("Agentic Engine for Minimal Resources", "subtitle"));
    const std::array<Glib::ustring, 7> names = {"1. Run Agent on Existing Project", "2. Generate New Project Template", "3. Run Hardware Benchmark", "4. Import Filled Project Template", "5. Generate Project From a Description", "6. Settings", "0. Exit"};
    for (unsigned i=0; i < names.size(); ++i) { auto* b=choice(names[i]); if(i==0)b->signal_clicked().connect(sigc::mem_fun(*this,&AgemirWindow::show_run)); if(i==1)b->signal_clicked().connect([this]{start(AGEMIR_GENERATE_TEMPLATE);}); if(i==2)b->signal_clicked().connect(sigc::mem_fun(*this,&AgemirWindow::show_benchmark)); if(i==3)b->signal_clicked().connect(sigc::mem_fun(*this,&AgemirWindow::show_import)); if(i==4)b->signal_clicked().connect(sigc::mem_fun(*this,&AgemirWindow::show_generate)); if(i==5)b->signal_clicked().connect(sigc::mem_fun(*this,&AgemirWindow::show_settings)); if(i==6)b->signal_clicked().connect(sigc::mem_fun(*this,&AgemirWindow::confirm_close)); main_page_.append(*b); }
    status_.set_halign(Gtk::Align::START); status_.set_wrap(); main_page_.append(status_);
    auto* log_scroll=Gtk::make_managed<Gtk::ScrolledWindow>(); log_.set_editable(false); log_.set_wrap_mode(Gtk::WrapMode::WORD_CHAR); log_scroll->set_child(log_); log_scroll->set_min_content_height(120); main_page_.append(*text("Activity", "field-label")); main_page_.append(*log_scroll); page(main_page_); stack_.add(main_page_, "main");

    run_page_.append(*text("Run Agent on Existing Project", "title")); run_page_.append(*text("Select a registered project. A later run automatically resumes saved work.", "subtitle")); projects_.set_selection_mode(Gtk::SelectionMode::SINGLE); run_page_.append(projects_); auto* run=Gtk::make_managed<Gtk::Button>("Run selected project"); run->add_css_class("suggested-action"); run->signal_clicked().connect([this]{auto* row=projects_.get_selected_row(); if(!row){alert("Invalid option","Select a registered project.",true);return;} start(AGEMIR_RUN_PROJECT,row->get_name());}); run_page_.append(*run); run_page_.append(pause_); pause_.set_sensitive(false); pause_.signal_clicked().connect(sigc::mem_fun(*this,&AgemirWindow::request_pause)); page(run_page_); stack_.add(run_page_,"run");

    generate_page_.append(*text("Generate Project From a Description", "title")); generated_name_.set_placeholder_text("letters, numbers, _ and -"); generated_path_.set_placeholder_text("Destination folder"); auto* pick=Gtk::make_managed<Gtk::Button>("Choose folder…"); pick->signal_clicked().connect([this]{choose_file(generated_path_,true);}); auto* row=Gtk::make_managed<Gtk::Box>(Gtk::Orientation::HORIZONTAL,8);row->append(generated_path_);row->append(*pick); generated_description_.set_wrap_mode(Gtk::WrapMode::WORD_CHAR);generated_description_.set_size_request(-1,150);field(generate_page_,"Project name",generated_name_);field(generate_page_,"Project folder",*row);field(generate_page_,"Describe the project",generated_description_);generate_page_.append(generated_graphical_);auto* create=Gtk::make_managed<Gtk::Button>("Generate project");create->add_css_class("suggested-action");create->signal_clicked().connect([this]{start(AGEMIR_GENERATE_PROJECT,generated_path_.get_text(),generated_name_.get_text(),generated_description_.get_buffer()->get_text(),{},generated_graphical_.get_active());});generate_page_.append(*create);page(generate_page_);stack_.add(generate_page_,"generate");

    import_page_.append(*text("Import Filled Project Template", "title")); auto* pick_template=Gtk::make_managed<Gtk::Button>("Choose template file…");pick_template->signal_clicked().connect([this]{choose_file(import_template_,false);});auto* template_row=Gtk::make_managed<Gtk::Box>(Gtk::Orientation::HORIZONTAL,8);template_row->append(import_template_);template_row->append(*pick_template);auto* pick_destination=Gtk::make_managed<Gtk::Button>("Choose folder…");pick_destination->signal_clicked().connect([this]{choose_file(import_path_,true);});auto* destination_row=Gtk::make_managed<Gtk::Box>(Gtk::Orientation::HORIZONTAL,8);destination_row->append(import_path_);destination_row->append(*pick_destination);field(import_page_,"Filled template",*template_row);field(import_page_,"Project folder",*destination_row);auto* import=Gtk::make_managed<Gtk::Button>("Import project");import->add_css_class("suggested-action");import->signal_clicked().connect([this]{start(AGEMIR_IMPORT_TEMPLATE,import_path_.get_text(),{},import_template_.get_text());});import_page_.append(*import);page(import_page_);stack_.add(import_page_,"import");

    benchmark_page_.append(*text("Run Hardware Benchmark", "title"));benchmark_page_.append(*text("This runs the CLI benchmark with qwen2.5-coder:1.5b. It may start Ollama and download that model.","subtitle"));auto* benchmark=Gtk::make_managed<Gtk::Button>("Run benchmark");benchmark->add_css_class("suggested-action");benchmark->signal_clicked().connect([this]{start(AGEMIR_RUN_BENCHMARK);});benchmark_page_.append(*benchmark);page(benchmark_page_);stack_.add(benchmark_page_,"benchmark");

    settings_page_.append(*text("Settings", "title"));field(settings_page_,"Name",user_name_);language_.set_model(Gtk::StringList::create({"English","Español","Français","Deutsch","日本語"}));field(settings_page_,"Language",language_);current_model_.set_halign(Gtk::Align::START);settings_page_.append(current_model_);settings_page_.append(automatic_model_);catalog_model_.set_model(Gtk::StringList::create({}));field(settings_page_,"Catalog model",catalog_model_);custom_model_.set_placeholder_text("Other Ollama model tag (optional)");field(settings_page_,"Other model",custom_model_);auto* save=Gtk::make_managed<Gtk::Button>("Save settings");save->add_css_class("suggested-action");save->signal_clicked().connect([this]{const auto custom=custom_model_.get_text();std::string model="auto";if(!custom.empty())model=custom;else if(!automatic_model_.get_active()){auto values=std::dynamic_pointer_cast<Gtk::StringList>(catalog_model_.get_model());if(values&&catalog_model_.get_selected()!=GTK_INVALID_LIST_POSITION)model=values->get_string(catalog_model_.get_selected());}const auto lang=std::to_string(language_.get_selected()+1);bool ok=runtime_&&agemir_runtime_set_setting(runtime_,"username",user_name_.get_text().c_str())&&agemir_runtime_set_setting(runtime_,"language",lang.c_str())&&agemir_runtime_set_setting(runtime_,"model",model.c_str());if(!ok){alert("Settings were not saved","Name and model tag must be non-empty and contain no line breaks.",true);return;}refresh_settings();set_status("Settings saved.");});settings_page_.append(*save);page(settings_page_);stack_.add(settings_page_,"settings");
    set_child(stack_); completed_.connect(sigc::mem_fun(*this,&AgemirWindow::finish_request));signal_close_request().connect([this]{confirm_close();return true;}, false);refresh_settings();set_status(runtime_?"Ready.":"Could not initialize the Agemir C runtime.",!runtime_);show_main();
}
AgemirWindow::~AgemirWindow(){status_poll_.disconnect();if(worker_.joinable())worker_.join();agemir_runtime_destroy(runtime_);}
void AgemirWindow::show_main(){stack_.set_visible_child("main");} void AgemirWindow::show_run(){refresh_projects();stack_.set_visible_child("run");} void AgemirWindow::show_generate(){stack_.set_visible_child("generate");} void AgemirWindow::show_import(){stack_.set_visible_child("import");} void AgemirWindow::show_benchmark(){stack_.set_visible_child("benchmark");} void AgemirWindow::show_settings(){refresh_settings();stack_.set_visible_child("settings");}
void AgemirWindow::refresh_projects(){while(auto* child=projects_.get_first_child())projects_.remove(*child);const int n=runtime_?agemir_runtime_project_count(runtime_):0;if(n<1)projects_.append(*text("No registered projects. Import or generate a project first.","subtitle"));for(int i=0;i<n;++i){AgemirProject p{};if(!agemir_runtime_project_at(runtime_,i,&p))continue;auto* r=Gtk::make_managed<Gtk::ListBoxRow>();r->set_name(p.path);auto* l=text(Glib::ustring(p.name)+"\n"+p.path);r->set_child(*l);projects_.append(*r);}}
void AgemirWindow::refresh_settings(){if(!runtime_)return;std::array<char,128> value{};if(agemir_runtime_get_setting(runtime_,"username",value.data(),value.size()))user_name_.set_text(value.data());if(agemir_runtime_get_setting(runtime_,"language",value.data(),value.size()))language_.set_selected(std::max(1,atoi(value.data()))-1);std::array<char,64> resolved{},saved{};int automatic=0;if(agemir_runtime_current_model(runtime_,resolved.data(),resolved.size(),&automatic))current_model_.set_text(std::string("Current model: ")+resolved.data()+(automatic?" (automatic)":""));agemir_runtime_get_setting(runtime_,"model",saved.data(),saved.size());automatic_model_.set_active(std::string(saved.data())=="auto");custom_model_.set_text(std::string(saved.data())=="auto"?"":saved.data());auto values=Gtk::StringList::create({});for(int i=0;i<agemir_runtime_model_count(runtime_);++i){AgemirModel m{};if(agemir_runtime_model_at(runtime_,i,&m))values->append(m.tag);}catalog_model_.set_model(values);}
void AgemirWindow::start(AgemirOperation op,const std::string& path,const std::string& name,const std::string& description,const std::string& model,bool graphical){if(!runtime_||busy_)return;if((op==AGEMIR_RUN_PROJECT&&path.empty())||(op==AGEMIR_GENERATE_PROJECT&&(path.empty()||name.empty()||description.empty()))||(op==AGEMIR_IMPORT_TEMPLATE&&(path.empty()||description.empty()))){alert("Invalid option","Complete the required fields before continuing.",true);return;}if(worker_.joinable())worker_.join();busy_=true;active_run_=op==AGEMIR_RUN_PROJECT;pause_requested_=false;active_project_path_=path;append_log("Started an Agemir operation.");set_status("Working…");worker_=std::thread([this,op,path,name,description,model,graphical]{AgemirRequest r{};r.operation=op;r.project_path=path.empty()?nullptr:path.c_str();r.project_name=name.empty()?nullptr:name.c_str();r.description=description.empty()?nullptr:description.c_str();r.model=model.empty()?nullptr:model.c_str();r.graphical=graphical;std::array<char,512> error{};bool ok=agemir_runtime_execute(runtime_,&r,error.data(),error.size())!=0;{std::lock_guard<std::mutex> lock(result_mutex_);result_ok_=ok;result_message_=error[0]?error.data():(ok?"Completed.":"The operation did not complete.");}completed_.emit();});status_poll_=Glib::signal_timeout().connect(sigc::mem_fun(*this,&AgemirWindow::refresh_status),400);}
void AgemirWindow::finish_request(){if(worker_.joinable())worker_.join();status_poll_.disconnect();busy_=false;std::lock_guard<std::mutex> lock(result_mutex_);append_log(result_message_);set_status(result_message_,!result_ok_);alert(result_ok_?"Agemir":"Agemir error",result_message_,!result_ok_);show_main();}
bool AgemirWindow::refresh_status(){if(!busy_||!active_run_||!runtime_)return busy_;AgemirStatus s{};if(!agemir_runtime_get_status(runtime_,active_project_path_.c_str(),&s))return true;std::string value=s.state;if(s.task[0])value+=" · "+std::string(s.task);if(s.attempts)value+=" · attempt "+std::to_string(s.attempts);if(s.reason[0])value+=" · "+std::string(s.reason);set_status(value,std::string(s.state)=="failed"||std::string(s.state)=="error");pause_.set_sensitive(std::string(s.state)=="running"&&!pause_requested_);return true;}
void AgemirWindow::request_pause(){std::array<char,256> error{};if(runtime_&&agemir_runtime_pause(runtime_,active_project_path_.c_str(),error.data(),error.size())){pause_requested_=true;pause_.set_sensitive(false);set_status("Pause requested. Agemir stops at the next safe checkpoint.");}else alert("Could not pause",error.data(),true);}
void AgemirWindow::choose_file(Gtk::Entry& target,bool folder){chooser_target_=&target;chooser_=Gtk::FileChooserNative::create(folder?"Choose project folder":"Choose filled template",*this,folder?Gtk::FileChooser::Action::SELECT_FOLDER:Gtk::FileChooser::Action::OPEN,"Select","Cancel");chooser_->signal_response().connect(sigc::mem_fun(*this,&AgemirWindow::complete_choose));chooser_->show();}void AgemirWindow::complete_choose(int response){if(response==Gtk::ResponseType::ACCEPT&&chooser_target_){auto f=chooser_->get_file();if(f)chooser_target_->set_text(f->get_path());}chooser_target_=nullptr;chooser_.reset();}
void AgemirWindow::set_status(const Glib::ustring& value,bool error){status_.set_text(value);status_.remove_css_class("status-ok");status_.remove_css_class("status-error");status_.add_css_class(error?"status-error":"status-ok");}void AgemirWindow::append_log(const Glib::ustring& value){log_.get_buffer()->insert(log_.get_buffer()->end(),value+"\n");}void AgemirWindow::alert(const Glib::ustring& title,const Glib::ustring& detail,bool error){auto d=Gtk::AlertDialog::create(title);d->set_detail(detail);if(error)d->set_default_button(0);d->show(*this);}void AgemirWindow::confirm_close(){if(busy_){alert("Agemir is still running","Pause or let the current operation finish before closing.",true);return;}auto d=Gtk::AlertDialog::create("Exit Agemir?");d->set_detail("The command-line equivalent returns to the shell.");d->set_buttons({"Cancel","Exit"});d->set_cancel_button(0);d->set_default_button(1);d->choose(*this,[this,d](Glib::RefPtr<Gio::AsyncResult>& r){if(d->choose_finish(r)==1)set_visible(false);});}
